const $=s=>document.querySelector(s);
let token=localStorage.getItem("novabank_token")||"", me=null, accounts=[], availableCards=[], verifiedRecipient="";
const money=cents=>(Number(cents||0)/100).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2});
function notice(msg,error=false){const n=$("#notice");if(!n){console[error?"error":"log"](msg);return;}n.textContent=msg;n.classList.remove("hidden","error");if(error)n.classList.add("error");setTimeout(()=>n.classList.add("hidden"),6500)}
async function api(path,opts={}){const headers={"content-type":"application/json",...(opts.headers||{})};if(token)headers.authorization="Bearer "+token;let res;try{res=await fetch("/api"+path,{...opts,headers});}catch(e){throw new Error("API se connection nahi ho pa raha. Cloudflare par deploy hone ke baad try karein.");}let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||"Request failed");return data}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function setAuth(show){const auth=$("#authPanel"),dashboard=$("#dashboard"),logout=$("#logoutBtn");if(show){dashboard?.classList.add("hidden");auth?.classList.add("hidden");document.body.classList.remove("modal-open");if($("#openLoginModal"))$("#openLoginModal").classList.remove("hidden");if($("#openAccountModal"))$("#openAccountModal").classList.remove("hidden");}else{dashboard?.classList.remove("hidden");auth?.classList.add("hidden");document.body.classList.remove("modal-open");if($("#openLoginModal"))$("#openLoginModal").classList.add("hidden");if($("#openAccountModal"))$("#openAccountModal").classList.add("hidden");}logout?.classList.toggle("hidden",show)}
function openAuthModal(which){const a=$("#authPanel");if(!a)return;a.classList.remove("hidden","show-login","show-register");a.classList.add(which==="register"?"show-register":"show-login");document.body.classList.add("modal-open");$("#authModalTitle").textContent=which==="register"?"Open Account":"Customer Login";$("#modalLoginTab")?.classList.toggle("active",which!=="register");$("#modalAccountTab")?.classList.toggle("active",which==="register");setTimeout(()=>a.querySelector(which==="register"?'#registerForm input[name="displayName"]':'#loginForm input[name="login"]')?.focus(),80)}
function closeAuthModal(){const a=$("#authPanel");a?.classList.add("hidden");a?.classList.remove("show-login","show-register");document.body.classList.remove("modal-open")}
$("#openLoginModal")?.addEventListener("click",()=>openAuthModal("login"));$("#openAccountModal")?.addEventListener("click",()=>openAuthModal("register"));$("#heroOpenAccount")?.addEventListener("click",()=>openAuthModal("register"));$("#closeAuthModal")?.addEventListener("click",closeAuthModal);$("#modalLoginTab")?.addEventListener("click",()=>openAuthModal("login"));$("#modalAccountTab")?.addEventListener("click",()=>openAuthModal("register"));$("#authPanel")?.addEventListener("click",e=>{if(e.target.id==="authPanel")closeAuthModal()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeAuthModal()});$("#heroExploreOffers")?.addEventListener("click",()=>document.querySelector(".promo-wrap")?.scrollIntoView({behavior:"smooth",block:"center"}));
const currentType=$('#registerForm select[name="accountType"]');function updateCurrentFields(){const box=$('#currentBusinessFields'),isCurrent=currentType?.value==='current';box?.classList.toggle('hidden',!isCurrent);box?.querySelectorAll('input,select').forEach(el=>{el.required=isCurrent})}currentType?.addEventListener('change',updateCurrentFields);updateCurrentFields();
let promoIndex=0;const promoSlides=[...document.querySelectorAll('.promo-slide')],promoDots=[...document.querySelectorAll('.promo-dot')];function showPromo(i){if(!promoSlides.length)return;promoIndex=(i+promoSlides.length)%promoSlides.length;promoSlides.forEach((el,n)=>el.classList.toggle('active',n===promoIndex));promoDots.forEach((el,n)=>el.classList.toggle('active',n===promoIndex))}$('#promoPrev')?.addEventListener('click',()=>showPromo(promoIndex-1));$('#promoNext')?.addEventListener('click',()=>showPromo(promoIndex+1));promoDots.forEach((b,i)=>b.addEventListener('click',()=>showPromo(i)));if(promoSlides.length)setInterval(()=>{if(!document.hidden)showPromo(promoIndex+1)},6500);
async function forceCustomerPasswordChange(currentPassword){const next=prompt("Security update required. Choose a new password (12–128 characters):");if(next===null){await api("/logout",{method:"POST",body:"{}"}).catch(()=>{});token="";localStorage.removeItem("novabank_token");throw Error("Please sign in again when you are ready to change the temporary password.")}const confirmNext=prompt("Re-enter your new password:");if(next!==confirmNext||next.length<12||next.length>128){await api("/logout",{method:"POST",body:"{}"}).catch(()=>{});token="";localStorage.removeItem("novabank_token");throw Error("Passwords did not match or were shorter than 12 characters. Please sign in again to retry.")}const r=await api("/change-password",{method:"POST",body:JSON.stringify({currentPassword,newPassword:next})});notice(r.message||"Password changed successfully.")}
const forgotForm=$("#forgotPasswordForm"), recoveryRequestForm=$("#recoveryRequestForm");
function showAuthRecovery(which){openAuthModal("login");$("#loginForm")?.classList.add("hidden");$(".auth-assistance")?.classList.add("hidden");forgotForm?.classList.toggle("hidden",which!=="password");recoveryRequestForm?.classList.toggle("hidden",which!=="request");if(which==="request")recoveryRequestForm?.querySelector('input[name="lookup"]')?.focus();else forgotForm?.querySelector('input[name="username"]')?.focus()}
$("#openRecoveryModal")?.addEventListener("click",()=>showAuthRecovery("request"));
$("#showRecoveryRequest")?.addEventListener("click",()=>showAuthRecovery("request"));
$("#openHelpModal")?.addEventListener("click",()=>{openAuthModal("login");$("#loginForm")?.classList.add("hidden");$(".auth-assistance")?.classList.add("hidden");forgotForm?.classList.add("hidden");recoveryRequestForm?.classList.remove("hidden");const title=$("#authModalTitle");if(title)title.textContent="Help & Account Access";const copy=recoveryRequestForm?.querySelector("p");if(copy)copy.textContent="Need help signing in, forgot your username/email, or need a password reset? Submit one request for Super Admin review.";});
$("#cancelRecoveryRequest")?.addEventListener("click",()=>{recoveryRequestForm?.reset();recoveryRequestForm?.classList.add("hidden");forgotForm?.classList.add("hidden");$("#loginForm")?.classList.remove("hidden");$(".auth-assistance")?.classList.remove("hidden");const title=$("#authModalTitle");if(title)title.textContent="Customer Login"});
recoveryRequestForm?.addEventListener("submit",async e=>{e.preventDefault();const d=formData(recoveryRequestForm);try{const r=await api("/password-recovery",{method:"POST",body:JSON.stringify({accountNumber:d.lookup,requestType:d.requestType})});recoveryRequestForm.reset();recoveryRequestForm.classList.add("hidden");$("#loginForm")?.classList.remove("hidden");$(".auth-assistance")?.classList.remove("hidden");notice(r.message||"If the details match a demo account, a request has been sent for Super Admin review.");}catch(err){notice(err.message,true)}});

$("#showForgotPassword")?.addEventListener("click",()=>{ $("#loginForm")?.classList.add("hidden"); $(".auth-assistance")?.classList.add("hidden"); forgotForm?.classList.remove("hidden"); recoveryRequestForm?.classList.add("hidden"); const loginValue=$("#loginForm input[name=login]")?.value||""; if(loginValue && !loginValue.includes("@")) forgotForm.elements.username.value=loginValue; });
$("#cancelForgotPassword")?.addEventListener("click",()=>{forgotForm?.reset();forgotForm?.classList.add("hidden");$("#loginForm")?.classList.remove("hidden");$(".auth-assistance")?.classList.remove("hidden");});
forgotForm?.addEventListener("submit",async e=>{e.preventDefault();try{const d=formData(forgotForm);if(d.newPassword!==d.confirmPassword)throw new Error("New password and confirmation do not match.");if(d.newPassword.length<10)throw new Error("Password must be at least 10 characters.");const r=await api("/forgot-password",{method:"POST",body:JSON.stringify({username:d.username,customerId:d.customerId,newPassword:d.newPassword})});forgotForm.reset();forgotForm.classList.add("hidden");$("#loginForm")?.classList.remove("hidden");$(".auth-assistance")?.classList.remove("hidden");if($("#loginForm input[name=login]"))$("#loginForm input[name=login]").value=d.username;notice(r.message||"If the details matched, the password has been reset.");}catch(err){notice(err.message,true)}});

$("#loginForm").addEventListener("submit",async e=>{e.preventDefault();try{const form=formData(e.target);const d=await api("/login",{method:"POST",body:JSON.stringify(form)});token=d.token;localStorage.setItem("novabank_token",token);if(d.user?.mustChangePassword)await forceCustomerPasswordChange(String(form.password||""));await loadDashboard();closeAuthModal();const hr=new Date().getHours(),greeting=hr<12?"Good morning":hr<17?"Good afternoon":hr<21?"Good evening":"Good night";notice(`${greeting}, ${me?.display_name||me?.displayName||me?.username||"welcome back"}!`);}catch(err){token="";localStorage.removeItem("novabank_token");setAuth(true);notice(err.message,true)}});
$("#registerForm").addEventListener("submit",async e=>{e.preventDefault();try{await api("/register",{method:"POST",body:JSON.stringify(formData(e.target))});const createdUsername=e.target.elements.username?.value||"";e.target.reset();updateCurrentFields();closeAuthModal();openAuthModal("login");if(createdUsername&&$("#loginForm input[name=login]"))$("#loginForm input[name=login]").value=createdUsername;notice("Demo account created successfully. Ab login karein.");}catch(err){notice(err.message,true)}});
$("#logoutBtn").addEventListener("click",async()=>{try{await api("/logout",{method:"POST",body:"{}"})}catch{}token="";me=null;localStorage.removeItem("novabank_token");setAuth(true);notice("You have been logged out.");});
async function verifyRecipient(){const input=$("#recipientAccountNumber"),status=$("#transferRecipientStatus");if(!input||!status)return false;const accountNumber=input.value.trim();verifiedRecipient="";status.className="";if(!accountNumber){status.textContent="Enter the account number to verify the registered demo account name.";return false;}status.textContent="Verifying demo account…";try{const result=await api(`/recipient-lookup?accountNumber=${encodeURIComponent(accountNumber)}`);verifiedRecipient=result.accountNumber;status.className="valid";status.textContent=`Verified recipient: ${result.recipientName} · ${result.accountNumber}`;return true;}catch(err){status.className="invalid";status.textContent=err.message;return false;}}
function updateTransferSource(){const method=$("#transferPaymentMethod")?.value||"account",accountLabel=$("#transferAccountSourceLabel"),cardLabel=$("#transferCardSourceLabel"),cardSelect=$("#fromCreditCard"),fee=$("#transferFeeInfo");if(accountLabel)accountLabel.classList.toggle("hidden",method!=="account");if(cardLabel)cardLabel.classList.toggle("hidden",method!=="credit_card");const accountSelect=$("#fromAccount");if(accountSelect)accountSelect.required=method==="account";if(cardSelect)cardSelect.required=method==="credit_card";if(fee)fee.textContent=method==="credit_card"?"A 0.9% demo fee is added to the card outstanding. Transfers require an active card and sufficient available credit.":"Account transfers have no demo fee.";}
$("#transferPaymentMethod")?.addEventListener("change",updateTransferSource);
$("#recipientAccountNumber")?.addEventListener("blur",verifyRecipient);
$("#recipientAccountNumber")?.addEventListener("input",()=>{verifiedRecipient="";const status=$("#transferRecipientStatus");if(status){status.className="";status.textContent="Verify the account number before transferring.";}});
$("#transferForm").addEventListener("submit",async e=>{e.preventDefault();try{const input=$("#recipientAccountNumber");if(!verifiedRecipient||verifiedRecipient!==input.value.trim()){const ok=await verifyRecipient();if(!ok)throw new Error("Recipient account verify hone ke baad hi transfer proceed hoga.");}const d=formData(e.target);d.amount=Number(d.amount);d.paymentMethod=$("#transferPaymentMethod")?.value||"account";if(d.paymentMethod==="credit_card"){d.fromCreditCardId=$("#fromCreditCard")?.value||"";if(!d.fromCreditCardId)throw new Error("Select an active demo credit card first.");}const r=await api("/transfer",{method:"POST",body:JSON.stringify(d)});e.target.reset();verifiedRecipient="";await loadDashboard();notice(r.message)}catch(err){notice(err.message,true)}});
for (const [formId, requestType] of [["#depositForm","deposit"],["#withdrawForm","withdrawal"]]) {
  $(formId).addEventListener("submit",async e=>{
    e.preventDefault();
    try {
      const d=formData(e.target); d.amount=Number(d.amount); d.type=requestType;
      const r=await api("/money-requests",{method:"POST",body:JSON.stringify(d)});
      e.target.reset(); await loadDashboard();
      notice(`${r.message} Request ID: ${r.requestId}`);
    } catch(err) { notice(err.message,true); }
  });
}

["#statementFrom","#statementTo","#statementType"].forEach(sel=>$(sel)?.addEventListener("change",()=>renderStatement(window.__transactions||[])));
$("#exportStatement")?.addEventListener("click",()=>exportStatement());
$("#loanForm").addEventListener("submit",async e=>{e.preventDefault();try{const d=formData(e.target);["requestedAmount","monthlyIncome","monthlyExpenses","existingEmi","tenureMonths"].forEach(k=>d[k]=Number(d[k]||0));const r=await api("/loans",{method:"POST",body:JSON.stringify(d)});e.target.reset();closeApplicationModal();await loadDashboard();notice(`${r.message} Application No: ${r.applicationNumber}. Suggested eligibility: N₹${money(r.suggestedEligibility*100)}.`)}catch(err){notice(err.message,true)}});
$("#cardForm")?.addEventListener("submit",async e=>{
  e.preventDefault();
  const form=e.currentTarget, status=$("#cardSubmitStatus"), submit=form.querySelector('button[type="submit"]');
  const showStatus=(message,isError=false)=>{if(status){status.textContent=message;status.classList.toggle("error",isError);status.classList.toggle("success",!isError);}};
  if(submit){submit.disabled=true;submit.dataset.originalText=submit.textContent;submit.textContent="Submitting application…";}
  showStatus("Submitting your application for bank assessment. Please wait…");
  try{
    const d=formData(form);
    ["monthlyIncome","monthlyExpenses","existingEmi","existingDebt","loanOutstanding"].forEach(k=>d[k]=Number(d[k]||0));
    const r=await api("/cards",{method:"POST",body:JSON.stringify(d)});
    showStatus(r.message||"Your card application has been submitted successfully.");
    form.reset();
    closeApplicationModal();
    notice(`${r.message||"Card application submitted."} Application No: ${r.applicationNumber}. Suggested limit: N₹${money(Number(r.suggestedLimit||0)*100)}.`);
    try{await loadDashboard();}catch(refreshError){console.error("Dashboard refresh after card application:",refreshError);}
  }catch(err){
    console.error("Card application submission failed:",err);
    showStatus(err.message||"Unable to submit the card application. Please try again.",true);
    notice(err.message||"Unable to submit the card application.",true);
  }finally{
    if(submit){submit.disabled=false;submit.textContent=submit.dataset.originalText||"Submit for bank assessment →";}
  }
});
$("#refreshAdmin").addEventListener("click",()=>Promise.all([loadAdmin(),loadMoneyRequests(),loadClosureRequests()]).catch(e=>notice(e.message,true)));
$("#offerForm").addEventListener("submit",async e=>{e.preventDefault();try{const d=formData(e.target);await api("/admin/offers",{method:"POST",body:JSON.stringify(d)});e.target.reset();await loadOffers();notice("Demo offer published.");}catch(err){notice(err.message,true)}});
async function loadOffers(){const d=await api("/offers");const offers=d.offers||[];const grid=$("#offersGrid");grid.innerHTML=offers.filter(x=>me?.role==="admin"||Number(x.active)===1).map(x=>`<article class="offer-card"><div class="offer-top"><span class="offer-category">${esc(x.category)}</span><span class="offer-star">✦</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p>${x.benefit?`<div class="offer-benefit">${esc(x.benefit)}</div>`:""}<button class="btn ${x.category==="Personal Loan"?"primary":"secondary"}" type="button" onclick="offerAction('${esc(x.category)}')">${esc(x.cta_label||"Explore offer")} →</button></article>`).join("")||'<p class="empty">No active offers right now.</p>';
const admin=$("#adminOffers");if(admin)admin.innerHTML=me?.role==="admin"?offers.map(x=>`<div class="activity-item"><div><strong>${esc(x.title)}</strong><small>${esc(x.category)} · ${Number(x.active)===1?"Active":"Inactive"}</small></div><button class="btn ghost" type="button" onclick="toggleOffer('${esc(x.id)}',${Number(x.active)===1?"false":"true"})">${Number(x.active)===1?"Deactivate":"Activate"}</button></div>`).join(""):'<p class="empty">Admin access required.</p>';
}
function openApplicationModal(type){
  const modal=$("#applicationModal");
  $("#loanApplicationContent").classList.toggle("hidden",type!=="loan");
  $("#cardOfferDetails").classList.toggle("hidden",type!=="card-details");
  $("#cardApplicationContent").classList.toggle("hidden",type!=="card-form");
  $("#modalTitle").textContent=type==="loan"?"Nova Flexi Loan": "Nova Rewards Card";
  $("#modalSubtitle").textContent=type==="loan"?"Apply for a fictional demo loan. Approval is not guaranteed.":"Fictional card application for learning and play only.";
  modal.classList.remove("hidden");
  document.body.classList.add("modal-open");
  const focusTarget=type==="loan"?$("#loanForm input"):type==="card-form"?$("#cardForm input"):$("#continueCardApplication");
  setTimeout(()=>focusTarget?.focus(),50);
}
function closeApplicationModal(){
  $("#applicationModal").classList.add("hidden");
  document.body.classList.remove("modal-open");
}
window.offerAction=(category)=>{
  if(category==="Personal Loan") openApplicationModal("loan");
  else if(category==="Credit Card") openApplicationModal("card-details");
  else if(category==="Shopping"||category==="Rewards") notice("This is a fictional simulator offer. Rewards are not real money.");
  else notice("This is a fictional simulator offer for learning and play.");
};
$("#closeApplicationModal").addEventListener("click",closeApplicationModal);
$("#backToDashboard").addEventListener("click",closeApplicationModal);
$("#continueCardApplication").addEventListener("click",()=>openApplicationModal("card-form"));
$("#applicationModal").addEventListener("click",e=>{if(e.target.id==="applicationModal")closeApplicationModal();});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#applicationModal").classList.contains("hidden"))closeApplicationModal();});
window.toggleOffer=async(id,active)=>{try{await api(`/admin/offers/${id}`,{method:"PATCH",body:JSON.stringify({active})});await loadOffers();notice(active?"Offer activated.":"Offer deactivated.");}catch(e){notice(e.message,true)}};
function displayDate(value){
  if(!value) return "Not available";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"});
}
function renderAccountInfo(){
  const account = accounts[0] || {};
  if($("#infoDisplayName"))$("#infoDisplayName").textContent = me?.display_name || me?.displayName || me?.username || "—";
  if($("#infoUsername"))$("#infoUsername").textContent = me?.username || "—";
  if($("#infoEmail"))$("#infoEmail").textContent = me?.email || "—";
  if($("#infoCustomerId"))$("#infoCustomerId").textContent = me?.id ? String(me.id).slice(0,8).toUpperCase() : "—";
  if($("#infoAccountNumber"))$("#infoAccountNumber").textContent = account.account_number || "No account found";
  if($("#infoAccountType"))$("#infoAccountType").textContent = account.account_type || account.type || "Everyday Demo Account";
  $("#infoAccountStatus").innerHTML = `<span class="status ${account.status==="active"?"status-active":""}">${esc(account.status || "Unknown")}</span>`;
  if($("#infoOpenedAt"))$("#infoOpenedAt").textContent = displayDate(account.opened_at || account.created_at);
  if($("#infoBalance"))$("#infoBalance").textContent = "N₹ " + money(accounts.reduce((sum,a)=>sum+Number(a.balance||0),0));
}
$("#copyAccountNumber")?.addEventListener("click",async()=>{
  const accountNumber = accounts[0]?.account_number;
  if(!accountNumber){notice("Account number is not available.",true);return;}
  try{ await navigator.clipboard.writeText(accountNumber); notice("Account number copied."); }
  catch{ notice("Copy is unavailable in this browser. Account number: " + accountNumber, true); }
});
let creditReportCache=null;
async function loadNovaFeatures(){
  try{const d=await api('/credit-intelligence');$('#novaCreditScore').textContent=`${d.score} / 900`;$('#novaCreditStatus').textContent=d.score>=750?'Strong internal score':d.score>=650?'Good internal score':d.score>=550?'Building credit history':'Needs improvement';$('#novaCreditUtilization').textContent=`${d.summary.utilization}%`;$('#novaCreditSubscription').textContent=d.subscription?`Active until ${new Date(d.subscription.expires_at).toLocaleDateString('en-IN')}`:'No active plan';$('#creditReportLocked').classList.toggle('hidden',d.reportUnlocked);$('#creditReportUnlocked').classList.toggle('hidden',!d.reportUnlocked);if(d.reportUnlocked)await loadNovaCreditReport();}catch(e){$('#novaCreditStatus').textContent=e.message;}
  try{const b=await api('/quickpay/beneficiaries');renderQuickPayBeneficiaries(b.beneficiaries||[]);}catch(e){$('#quickPayBeneficiaries').innerHTML=`<p class="empty">${esc(e.message)}</p>`;}
}
function renderQuickPayBeneficiaries(rows){const box=$('#quickPayBeneficiaries'),select=$('#quickPayBeneficiarySelect');if(!box||!select)return;box.innerHTML=rows.map(b=>`<div class="activity-item"><div><strong>${esc(b.beneficiary_name)} · ${esc(b.beneficiary_account_number)}</strong><small>${b.status==='active'?'Ready for instant transfer':b.status==='cooling'?`Cooling until ${new Date(b.eligible_at).toLocaleTimeString('en-IN')}`:'Blocked'}</small></div><button class="btn ghost" type="button" data-remove-beneficiary="${esc(b.id)}">Remove</button></div>`).join('')||'<p class="empty">No saved beneficiaries yet.</p>';select.innerHTML=rows.filter(b=>b.status==='active').map(b=>`<option value="${esc(b.id)}">${esc(b.beneficiary_name)} · ${esc(b.beneficiary_account_number)}</option>`).join('')||'<option value="">No eligible beneficiary yet</option>';box.querySelectorAll('[data-remove-beneficiary]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/quickpay/beneficiaries/${btn.dataset.removeBeneficiary}`,{method:'DELETE'});await loadNovaFeatures();notice('Beneficiary removed.')}catch(e){notice(e.message,true)}}));}
async function loadNovaCreditReport(){try{const d=await api('/credit-intelligence/report');creditReportCache=d.report;const r=d.report;$('#creditReportContent').innerHTML=`<div class="credit-report-grid"><div><small>Credit utilization</small><b>${r.creditUtilizationPercent}%</b></div><div><small>Card outstanding</small><b>N₹ ${money(r.cardOutstanding)}</b></div><div><small>Total card limit</small><b>N₹ ${money(r.cardLimit)}</b></div><div><small>Late EMIs</small><b>${r.lateEmis}</b></div><div><small>Suggested loan limit</small><b>N₹ ${money(r.suggestedLoanLimit)}</b></div><div><small>Suggested card limit</small><b>N₹ ${money(r.suggestedCardLimit)}</b></div></div><h4>Active Loans</h4>${(r.loans||[]).map(x=>`<div class="activity-item"><div><strong>${esc(x.loan_number||'Demo loan')} · ${esc(x.status)}</strong><small>Principal N₹ ${money(x.principal_amount)} · Outstanding N₹ ${money(x.outstanding_amount)}</small></div></div>`).join('')||'<p class="muted">No loan records.</p>'}<h4>Credit Cards</h4>${(r.cards||[]).map(x=>`<div class="activity-item"><div><strong>${esc(x.masked_number)} · ${esc(x.status)}</strong><small>Limit N₹ ${money(x.credit_limit)} · Outstanding N₹ ${money(x.outstanding)}</small></div></div>`).join('')||'<p class="muted">No card records.</p>'}<h4>Loan / Card Applications</h4>${[...(r.loanApplications||[]),...(r.cardApplications||[])].map(x=>`<div class="activity-item"><div><strong>${esc(x.application_number||'Application')} · ${esc(x.status)}</strong><small>Suggested limit N₹ ${money(x.suggested_limit||0)}</small></div></div>`).join('')||'<p class="muted">No applications.</p>'}<p class="tiny muted">Report generated ${new Date(r.generatedAt).toLocaleString('en-IN')} · Internal simulator assessment only.</p>`;}catch(e){notice(e.message,true)}}
function printNovaCreditReport(){if(!creditReportCache)return notice('Open the report first.',true);const r=creditReportCache;const rows=(r.loans||[]).map(x=>`<tr><td>${esc(x.loan_number||'Loan')}</td><td>${esc(x.status)}</td><td>${money(x.principal_amount)}</td><td>${money(x.outstanding_amount)}</td></tr>`).join('');const html=`<!doctype html><html><head><meta charset="utf-8"><title>NovaBank Credit Report</title><style>body{font:14px Arial;color:#172b3a;padding:32px}.brand{font-size:24px;font-weight:bold;color:#126b59}.muted{color:#657786;font-size:11px}.score{font-size:32px;font-weight:bold;margin:22px 0;color:#126b59}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.grid div{padding:12px;background:#f2f6f8}.grid small{display:block;color:#657786}table{width:100%;border-collapse:collapse;margin-top:18px}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.disclaimer{margin-top:30px;font-size:10px;color:#657786}@media print{body{padding:0}}</style></head><body><div class="brand">NOVABANK</div><div class="muted">NOVA CREDIT INTELLIGENCE · INTERNAL SIMULATOR REPORT</div><div class="score">Credit Score: ${$('#novaCreditScore').textContent}</div><div class="grid"><div><small>Credit utilization</small><b>${r.creditUtilizationPercent}%</b></div><div><small>Card outstanding</small><b>N₹ ${money(r.cardOutstanding)}</b></div><div><small>Total card limit</small><b>N₹ ${money(r.cardLimit)}</b></div><div><small>Late EMIs</small><b>${r.lateEmis}</b></div><div><small>Suggested loan limit</small><b>N₹ ${money(r.suggestedLoanLimit)}</b></div><div><small>Suggested card limit</small><b>N₹ ${money(r.suggestedCardLimit)}</b></div></div><h3>Loan History</h3><table><tr><th>Loan</th><th>Status</th><th>Principal</th><th>Outstanding</th></tr>${rows||'<tr><td colspan="4">No loan records</td></tr>'}</table><p class="disclaimer">Generated ${new Date(r.generatedAt).toLocaleString('en-IN')}. NovaBank Internal Simulator Credit Score; not an official CIBIL or credit bureau report. Fictional simulator only.</p><script>window.onload=()=>setTimeout(()=>window.print(),250)</script></body></html>`;const w=window.open('','_blank');if(!w)return notice('Allow pop-ups to print or save as PDF.',true);w.document.write(html);w.document.close();}
$('#printCreditReport')?.addEventListener('click',printNovaCreditReport);
document.querySelectorAll('[data-credit-plan]').forEach(btn=>btn.addEventListener('click',async()=>{const accountId=$('#creditSubscriptionAccount')?.value;if(!accountId)return notice('Select a payment account.',true);try{const r=await api('/credit-intelligence/subscribe',{method:'POST',body:JSON.stringify({plan:btn.dataset.creditPlan,accountId})});notice(`${r.message} Reference: ${r.reference}`);await loadDashboard();}catch(e){notice(e.message,true)}}));
